289	/**
290	 * ユーザーの月次カレンダーデータを取得
291	 */
292	export async function getUserMonthlyCalendar(userId: string, month: Date) {
293	  const supabase = await createSupabaseServerClient();
294	  const start = startOfMonth(month);
295	  const end = endOfMonth(month);
296	
297	  const { data, error } = await supabase
298	    .schema('attendance')
299	    .from('attendances')
300	    .select('date, type, timestamp')
301	    .eq('user_id', userId)
302	    .gte('date', format(start, 'yyyy-MM-dd'))
303	    .lte('date', format(end, 'yyyy-MM-dd'))
304	    .order('timestamp', { ascending: true });
305	
306	  if (error) {
307	    console.error('Error fetching monthly calendar:', error);
308	    return [];
309	  }
310	
311	  const dailyStatus: Record<string, { status: 'in' | 'out' | 'mixed'; count: number }> = {};
312	  
313	  (data || []).forEach(att => {
314	    if (!att.date) return;
315	    
316	    if (!dailyStatus[att.date]) {
317	      dailyStatus[att.date] = { status: att.type as 'in' | 'out', count: 1 };
318	    } else {
319	      dailyStatus[att.date].count++;
320	      if (dailyStatus[att.date].status !== att.type) {
321	        dailyStatus[att.date].status = 'mixed';
322	      }
323	    }
324	  });
325	
326	  return Object.entries(dailyStatus).map(([date, info]) => ({
327	    date,
328	    status: info.status,
329	    count: info.count
330	  }));
331	}
332	
333	/**
334	 * チームの平均出席率を計算
335	 */
336	export async function getTeamAverageAttendanceRate(teamId: string, days: number = 30): Promise<number> {
337	  const supabase = await createSupabaseAdminClient();
338	  const startDate = format(subDays(new Date(), days), 'yyyy-MM-dd');
339	
340	  // チームメンバーを取得
341	  const { data: teamMembers } = await supabase
342	    .schema('member')
343	    .from('member_team_relations')
344	    .select('member_id')
345	    .eq('team_id', teamId);
346	
347	  if (!teamMembers || teamMembers.length === 0) {
348	    return 0;
349	  }
350	
351	  const memberIds = teamMembers.map(m => m.member_id);
352	
353	  // 各メンバーの出席日数を計算
354	  let totalAttendanceDays = 0;
355	
356	  for (const memberId of memberIds) {
357	    const { data: attendances } = await supabase
358	      .schema('attendance')
359	      .from('attendances')
360	      .select('date')
361	      .eq('user_id', memberId)
362	      .eq('type', 'in')
363	      .gte('date', startDate);
364	
365	    if (attendances) {
366	      const uniqueDays = new Set(attendances.map(a => a.date)).size;
367	      totalAttendanceDays += uniqueDays;
368	    }
369	  }
370	
371	  const possibleDays = days * memberIds.length;
372	  return possibleDays > 0 ? (totalAttendanceDays / possibleDays) * 100 : 0;
373	}
374	
375	/**
376	 * 総活動時間を計算（特定ユーザー）
377	 */
378	export async function calculateTotalActivityTime(userId: string, days: number): Promise<number> {
379	  const supabase = await createSupabaseAdminClient();
380	  const startDate = format(subDays(new Date(), days), 'yyyy-MM-dd');
381	
382	  const { data: attendances } = await supabase
383	    .schema('attendance')
384	    .from('attendances')
385	    .select('*')
386	    .eq('user_id', userId)
387	    .gte('date', startDate)
388	    .order('timestamp', { ascending: true });
389	
390	  if (!attendances || attendances.length === 0) {
391	    return 0;
392	  }
393	
394	  let totalSeconds = 0;
395	  let lastInTime: Date | null = null;
396	
397	  for (const att of attendances) {
398	    if (att.type === 'in') {
399	      lastInTime = new Date(att.timestamp);
400	    } else if (att.type === 'out' && lastInTime) {
401	      const outTime = new Date(att.timestamp);
402	      totalSeconds += differenceInSeconds(outTime, lastInTime);
403	      lastInTime = null;
404	    }
405	  }
406	
407	  return totalSeconds;
408	}
409	
410	/**
411	 * 月次勤怠データを取得（カレンダー表示用）
412	 */
