415	  const start = startOfMonth(month);
416	  const end = endOfMonth(month);
417	
418	  const { data, error } = await supabase
419	    .schema('attendance')
420	    .from('attendances')
421	    .select('date, type')
422	    .eq('user_id', userId)
423	    .gte('date', format(start, 'yyyy-MM-dd'))
424	    .lte('date', format(end, 'yyyy-MM-dd'))
425	    .order('timestamp', { ascending: true });
426	
427	  if (error) {
428	    console.error('Error fetching monthly attendance:', error);
429	    return [];
430	  }
